1	import "server-only";
2	import { Prisma, type GameMod } from "@prisma/client";
3	import { db } from "@/lib/db";
4	import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
5	import type { ModSummary } from "@/lib/mods-catalog";
6	
7	/**
8	 * NxLabs taxonomy for the new marketing site: one clear category per mod,
9	 * computed at query time (no DB writes) from the mod's REAL source data.
10	 *
11	 * GameMod.category is one free-text value per mod in each source's own words
12	 * ("Workshop", "content", "tweaks", "Creatures", "Admin & Permissions", ...).
13	 * The classification, in order:
14	 *   1. the source category, when it already says what the mod is
15	 *      ("Performance", "Economy", "Creatures", "Weapons" ...) -> DIRECT;
16	 *   2. otherwise (generic buckets like "Workshop", "Mod", "content", or an
17	 *      unmapped niche one) keywords in the mod's NAME, then in the first 400
18	 *      characters of its DESCRIPTION (whole words only) -> RULES, first hit
19	 *      wins, most specific rules first;
20	 *   3. otherwise a few broad source buckets fall back (FALLBACK), and anything
21	 *      left is "other" — never a guess.
22	 * The same rules run in SQL (filters, counts) and in JS (card labels, mod
23	 * pages), so a filter and the label it shows always agree.
24	 */
25	export type TaxKey =
26	  | "performance" | "library" | "admin" | "economy" | "worldgen" | "maps" | "items" | "vehicles"
27	  | "cosmetics" | "qol" | "social" | "mobs" | "tech" | "modes" | "building" | "gameplay";
28	
29	export type TaxCat = {
30	  key: TaxKey; label: string; desc: string;
31	  /** tile illustration (mod_tags.py kinds + NxLabs extensions) */ ill: string;
32	  /** card banner illustration (mods_ui.py ILL + extensions) */ card: string;
33	  /** Aurora icon for small tiles */ icon: string;
34	  c1: string; c2: string;
35	};
36	
37	export const TAXONOMY: TaxCat[] = [
38	  { key: "performance", label: "Performance", desc: "Makes the game or server run faster or lighter without changing how it plays.", ill: "tick", card: "perf", icon: "bolt", c1: "#3FD89A", c2: "#3EDCF2" },
39	  { key: "library", label: "Libraries & compatibility", desc: "Foundations and fixes other mods build on. Usually installed because something else needs it.", ill: "nodes", card: "core", icon: "cpu", c1: "#6F8DFF", c2: "#B98CFF" },
40	  { key: "admin", label: "Admin & protection", desc: "Permissions, moderation, anti-cheat and land protection for the people running the server.", ill: "shield", card: "shield", icon: "shield", c1: "#FF9A5C", c2: "#FF5FA8" },
41	  { key: "economy", label: "Economy & shops", desc: "Currencies, shops, trading and rewards.", ill: "coin", card: "coin", icon: "card", c1: "#FFD27A", c2: "#FF9A5C" },
42	  { key: "worldgen", label: "World generation", desc: "Changes or adds to how new terrain, biomes and structures are created.", ill: "terrain", card: "wave", icon: "globe", c1: "#3FD89A", c2: "#4E8DFF" },
43	  { key: "maps", label: "Maps & scenarios", desc: "Custom maps, arenas and scenarios to play on.", ill: "pin", card: "pin", icon: "globe", c1: "#3EDCF2", c2: "#7B5CFF" },
44	  { key: "items", label: "Weapons, items & crafting", desc: "New weapons, gear, items and the recipes to make them.", ill: "blade", card: "blade", icon: "spark", c1: "#FF6FA8", c2: "#B98CFF" },
45	  { key: "vehicles", label: "Vehicles & ships", desc: "Cars, boats, aircraft, ships and other things to drive or fly.", ill: "car", card: "car", icon: "rocket", c1: "#4E8DFF", c2: "#3EDCF2" },
46	  { key: "cosmetics", label: "Cosmetics, visuals & audio", desc: "Skins, textures, shaders, models and sound — how the game looks and sounds.", ill: "brush", card: "brush", icon: "spark", c1: "#E04BD6", c2: "#7B3AF5" },
47	  { key: "qol", label: "Quality of life & UI", desc: "Small conveniences, tweaks and interface improvements players notice straight away.", ill: "gear", card: "gear", icon: "check", c1: "#FFB36B", c2: "#FF6FA8" },
48	  { key: "social", label: "Chat & community", desc: "Chat, voice, Discord, clans and other community features.", ill: "chat", card: "chat", icon: "users", c1: "#6FB8FF", c2: "#9B6BFF" },
49	  { key: "mobs", label: "Creatures & NPCs", desc: "Adds or changes creatures, NPCs and how they behave.", ill: "path", card: "paw", icon: "spark", c1: "#E04BD6", c2: "#FF6FA8" },
50	  { key: "tech", label: "Technology & automation", desc: "Machines, power, logistics and automation.", ill: "circuit", card: "circuit", icon: "terminal", c1: "#3EDCF2", c2: "#4E6BFF" },
51	  { key: "modes", label: "Game modes & minigames", desc: "Game modes, minigames and competitive formats for your server.", ill: "target", card: "target", icon: "game", c1: "#E04BD6", c2: "#7B3AF5" },
52	  { key: "building", label: "Building & decoration", desc: "Blocks, furniture, decorations and building tools.", ill: "cube", card: "cube", icon: "database", c1: "#FFD27A", c2: "#3FD89A" },
53	  { key: "gameplay", label: "Gameplay & overhauls", desc: "New mechanics, content and overhauls that change how the game plays.", ill: "wave", card: "wave", icon: "game", c1: "#3EDCF2", c2: "#4E8DFF" },
54	];
55	export const TAX: Record<string, TaxCat> = Object.fromEntries(TAXONOMY.map((t) => [t.key, t]));
56	export const isTaxKey = (k: string): k is TaxKey => k in TAX;
57	export const OTHER = { key: "other", label: "Other", c1: "#6F8DFF", c2: "#9B6BFF", card: "core" } as const;
58	
59	/** 1. source categories that already say what the mod is (lower-cased, trimmed). */
60	const DIRECT: Record<TaxKey, string[]> = {
61	  performance: ["performance", "optimization", "optimisation", "optimizations"],
62	  library: ["library", "library / dependency", "dependency", "core", "api", "libraries", "compatibility", "cross-play", "patch", "fix", "hotfix", "harmony patching", "code", "counterstrikesharp"],
63	  admin: ["admin", "admin & permissions", "admin tool", "protection", "server-specific"],
64	  economy: ["economy"],
65	  worldgen: ["worldgen", "world", "world generation", "structures", "flora", "grass", "underground"],
66	  maps: ["map", "custom theater", "scenarios"],
67	  items: ["items", "item", "weapons", "armor", "food", "crafting", "loot", "smithing", "metal", "drink", "alcohol", "resin", "fuel", "collectables"],
68	  vehicles: ["boat", "transportation", "mount"],
69	  cosmetics: ["cosmetics", "skin", "skins (tos risk)", "visual", "graphics", "texture pack", "shaders", "fashion", "clothing", "playermodel", "audio", "music", "bell", "symphony"],
70	  qol: ["qol", "quality of life", "gather & qol", "tweaks", "tweak", "utility", "utilities", "tools", "external tool", "user experience", "accessibility", "simplification", "hud", "localizations", "language", "translation", "teleport"],
71	  social: ["social", "chat", "chat & discord", "discord", "clans & social", "community", "roleplay"],
72	  mobs: ["mobs", "creatures", "animals", "npc", "npcs", "entity logic(ai)", "pets", "villagers", "dragons"],
73	  tech: ["technology", "mechanic", "mechanics", "automation", "script"],
74	  modes: ["minigames", "minigame", "game mode", "gun game & 1v1", "retakes", "surf/kz/bhop", "match & scrim", "practice", "pve & events", "mutator", "ranks & stats"],
75	  building: ["building", "furniture", "decoration", "blockset", "chisel", "object", "woodworking", "storage"],
76	  gameplay: ["gameplay", "overhaul", "total conversion", "mod-packs", "difficulty", "realism", "hardcore", "immersion", "immersive", "classes", "combat", "farming", "magic", "fantasy", "travel & exploration", "cheat", "fun"],
77	};
78	/** 2. whole-word keywords, most specific first (checked on the name, then the description). */
79	const RULES: [TaxKey, string][] = [
80	  ["performance", "performance|optimi[sz]ation|optimi[sz]es?|optimi[sz]ed|fps|lag|tps|ferritecore|lithium|modernfix"],
81	  ["library", "library|libraries|api|framework|dependency|dependencies|lib|mod ?loader|compat|compatibility|compatibility patch|bepinex|harmony|ue4ss|metamod|oxide"],
82	  ["admin", "admin|admins|administration|permissions?|moderation|ban|bans|kick|anti-?cheat|vanish|grief|griefing|land ?claims?|claims?|whitelist|logging"],
83	  ["modes", "game ?modes?|gamemodes?|minigames?|deathmatch|prop ?hunt|ttt|darkrp|murder|battle ?royale|bed ?wars|hide ?and ?seek|pvp|pve|jailbreak|deathrun|retakes?|surf|capture the flag|ctf|1v1|1 ?vs ?1|aim ?(map|training|exercise|botz)?|practice|training|kz|bhop|hns|arena ?mode"],
84	  ["economy", "economy|shops?|currency|money|dosh|trader|traders|trading|marketplace|auction"],
85	  ["vehicles", "vehicles?|cars?|trucks?|ships?|boats?|planes?|aircraft|helicopters?|heli|tanks?|jets?|trains?|rovers?|spaceships?|drones?|bikes?|motorcycles?|hilux|lada|jeep|suv|submarines?|cockpits?"],
86	  ["maps", "maps?|arena|scenario|scenarios|island|(gm|ttt|rp|de|cs|surf|ze|zs|kz|bhop|jb|mg|dr|kf|zm|ph|ba)_\\w+|kf-\\w+"],
87	  ["mobs", "mobs?|creatures?|animals?|npcs?|zombies?|monsters?|bosses|boss|pets?|dinos?|dinosaurs?|wildlife|enemies|enemy|villagers?|dragons?|fleshpound"],
88	  ["items", "weapons?|guns?|rifles?|pistols?|shotguns?|swords?|armou?r|items?|loot|crafting|recipes?|swep|sweps|ammo|pickaxes?|tools?|backpacks?|suits?|knife|knives|bows?|arccw|tfa|m9k"],
89	  ["tech", "machines?|automation|conveyors?|power|electric|electricity|generators?|reactors?|factory|logistics?|pipes?|circuits?|belts?|industrial|industry|programs?|ic10|scripts?|turrets?|filtration|silos?"],
90	  ["cosmetics", "skins?|textures?|retextures?|reskins?|shaders?|playermodels?|player ?models?|cosmetics?|clothes|clothing|outfits?|hair|hd|sounds?|music|audio|voices?|voice ?pack|announcer|waifu|anime"],
91	  ["social", "chat|discord|voice ?chat|clans?|spectate|radio"],
92	  ["building", "building|buildings|build|furniture|decor|decorations?|decorative|blocks?|prefabs?|walls?|doors?|interior|material ?swapper"],
93	  ["worldgen", "worldgen|biomes?|terrain|structures?|ruins|dungeons?|world ?generation|caves?|villages?|vegetation|trees|ores?|asteroids?|planets?"],
94	  ["qol", "qol|quality of life|tweaks?|utility|utilities|convenience|inventory|hud|ui|interface|menu|minimap|tooltips?|hotkeys?|stack|stacking|sorting|auto|reloader|pause|damage ?numbers|hit ?numbers|indicators?|compass|quick"],
95	  ["gameplay", "overhaul|rebalance|balance|realism|realistic|hardcore|difficulty|mechanics|gameplay|survival|levels?|leveling|skills?|classes|magic|spells?|quests?|events?|story|progression|expansion"],
96	];
97	/** 3. broad source buckets that still say "adds content to the game". */
98	const FALLBACK: Record<string, TaxKey> = { content: "gameplay", addon: "gameplay", mod: "gameplay", mods: "gameplay" };
99	
100	const DIRECT_OF: Record<string, TaxKey> = {};
101	for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) for (const c of cats) DIRECT_OF[c] = k;
102	// word boundaries where letters of ANY script count as word characters, as Postgres \m/\M do
103	const JS_RULES = RULES.map(([k, re]) => [k, new RegExp(`(?<![\\p{L}\\p{N}_])(${re})(?![\\p{L}\\p{N}_])`, "iu")] as const);
104	
105	/** The category of one mod (JS), exactly as classifySql() computes it in SQL. */
106	export function classify(m: { category: string; name: string; description: string | null }): TaxKey | "other" {
107	  const c = m.category.trim().toLowerCase();
108	  if (DIRECT_OF[c]) return DIRECT_OF[c];
109	  for (const [k, re] of JS_RULES) if (re.test(m.name)) return k;
110	  const d = (m.description ?? "").slice(0, 400);
111	  for (const [k, re] of JS_RULES) if (re.test(d)) return k;
112	  return FALLBACK[c] ?? "other";
113	}
114	export const taxOf = (m: { category: string; name: string; description: string | null }) => {
115	  const k = classify(m);
116	  return k === "other" ? null : TAX[k];
117	};
118	
119	/** The same classification as a SQL CASE expression over "GameMod". */
120	export function classifySql(): Prisma.Sql {
121	  const cat = Prisma.sql`lower(btrim("category"))`;
122	  const whens: Prisma.Sql[] = [];
123	  for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) whens.push(Prisma.sql`WHEN ${cat} IN (${Prisma.join(cats)}) THEN ${k}`);
124	  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN "name" ~* ${`\\m(${re})\\M`} THEN ${k}`);
125	  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN left(coalesce("description", ''), 400) ~* ${`\\m(${re})\\M`} THEN ${k}`);
126	  for (const [c, k] of Object.entries(FALLBACK)) whens.push(Prisma.sql`WHEN ${cat} = ${c} THEN ${k}`);
127	  return Prisma.sql`(CASE ${Prisma.join(whens, " ")} ELSE 'other' END)`;
128	}
129	
130	// ── the category index: every public mod's category, computed once per 10 minutes ──
131	// Classifying runs ~30 regexes over names/descriptions, too slow to repeat per
132	// request on a 64k-row catalogue, so the result (id, family, category and the
133	// sort keys only) is held in memory per server process and rebuilt in the
134	// background after 10 minutes. Counts, top-per-category and category filters
135	// all read it, so they always agree with each other.
136	type Row = { id: string; f: string; k: string; d: number | null; c: number; ft: boolean; n: string };
137	const TTL = 10 * 60 * 1000;
138	const g = globalThis as unknown as { __nxmTaxIdx?: { at: number; rows: Row[] }; __nxmTaxBuild?: Promise<Row[]> };
139	async function build(): Promise<Row[]> {
140	  const rows = await db.$queryRaw<{ id: string; f: string; k: string; d: number | null; c: Date; ft: boolean; n: string }[]>(Prisma.sql`
141	    SELECT "id", "gameFamily" AS f, ${classifySql()} AS k, "downloads" AS d, "createdAt" AS c, "featured" AS ft, "name" AS n
142	    FROM "GameMod" WHERE "active" = true AND "upstreamOk" = true`);
143	  const out = rows.map((r) => ({ id: r.id, f: r.f, k: r.k, d: r.d, c: r.c.getTime(), ft: r.ft, n: r.n }));
144	  g.__nxmTaxIdx = { at: Date.now(), rows: out };
145	  return out;
146	}
147	async function index(): Promise<Row[]> {
148	  const cur = g.__nxmTaxIdx;
149	  if (cur && Date.now() - cur.at < TTL) return cur.rows;
150	  const pending = (g.__nxmTaxBuild ??= build().finally(() => { g.__nxmTaxBuild = undefined; }));
151	  return cur ? cur.rows : pending; // stale-while-revalidate once warm
152	}
153	
154	export type TaxSort = "downloads" | "latest" | "featured";
155	const byDl = (a: Row, b: Row) => (b.d ?? -1) - (a.d ?? -1) || a.n.localeCompare(b.n);
156	const CMP: Record<TaxSort, (a: Row, b: Row) => number> = {
157	  downloads: byDl,
158	  latest: (a, b) => b.c - a.c,
159	  featured: (a, b) => Number(b.ft) - Number(a.ft) || byDl(a, b),
160	};
161	
162	/** Categories with their real counts, for one family or every game, largest first ("other" excluded). */
163	export async function categoryCounts(family?: string): Promise<{ cat: TaxCat; count: number }[]> {
164	  const by = new Map<string, number>();
165	  for (const r of await index()) if (!family || r.f === family) by.set(r.k, (by.get(r.k) ?? 0) + 1);
166	  return TAXONOMY.filter((t) => (by.get(t.key) ?? 0) > 0).map((t) => ({ cat: t, count: by.get(t.key)! })).sort((a, b) => b.count - a.count);
167	}
168	
169	/** Share of public mods in a real category (not "other"), for a family or overall. */
170	export async function coverage(family?: string) {
171	  const rows = (await index()).filter((r) => !family || r.f === family);
172	  const other = rows.filter((r) => r.k === "other").length;
173	  return { total: rows.length, categorized: rows.length - other, pct: rows.length ? (rows.length - other) / rows.length : 0 };
174	}
175	
176	/** The most-downloaded mod ids per category (one family, or every game with null). */
177	export async function topPerCategory(family: string | null, take: number): Promise<Record<string, string[]>> {
178	  const out: Record<string, Row[]> = {};
179	  for (const r of await index()) if (!family || r.f === family) (out[r.k] ??= []).push(r);
180	  return Object.fromEntries(Object.entries(out).map(([k, rs]) => [k, rs.sort(byDl).slice(0, take).map((r) => r.id)]));
181	}
182	
183	/** Ids of public mods matching a search (the same fields queryCatalogMods searches). */
184	async function searchIds(q: string, family?: string): Promise<Set<string>> {
185	  const like = `%${q.replace(/[\\%_]/g, (c) => `\\${c}`)}%`;
186	  const rows = await db.$queryRaw<{ id: string }[]>(Prisma.sql`
187	    SELECT "id" FROM "GameMod" WHERE "active" = true AND "upstreamOk" = true
188	    ${family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty}
189	    AND ("name" ILIKE ${like} OR "category" ILIKE ${like} OR "description" ILIKE ${like})`);
190	  return new Set(rows.map((r) => r.id));
191	}
192	
193	/**
194	 * Public mods — optionally one category, one family and a search — with a real
195	 * total and page. Same public filter and search fields as queryCatalogMods;
196	 * download sorts put mods without a count LAST (queryCatalogMods' Postgres
197	 * default puts them first).
198	 */
199	export async function queryMods(opts: { key?: TaxKey; family?: string; q?: string; sort?: TaxSort; page?: number; perPage?: number }) {
200	  const per = opts.perPage ?? 12;
201	  const q = (opts.q ?? "").trim();
202	  const hits = q ? await searchIds(q, opts.family) : null;
203	  const rows = (await index()).filter((r) => (!opts.family || r.f === opts.family) && (!opts.key || r.k === opts.key) && (!hits || hits.has(r.id)));
204	  const total = rows.length;
205	  const pages = Math.max(1, Math.ceil(total / per));
206	  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), pages);
207	  const ids = rows.sort(CMP[opts.sort ?? "downloads"]).slice((page - 1) * per, page * per).map((r) => r.id);
208	  return { mods: await cardsByIds(ids), total, page, totalPages: pages, perPage: per };
209	}
210	
211	/** Real per-game match counts for a category and/or search, in one pass. */
212	export async function countsByFamily(opts: { key?: TaxKey; q?: string }): Promise<Map<string, number>> {
213	  const q = (opts.q ?? "").trim();
214	  const hits = q ? await searchIds(q) : null;
215	  const out = new Map<string, number>();
216	  for (const r of await index()) if ((!opts.key || r.k === opts.key) && (!hits || hits.has(r.id))) out.set(r.f, (out.get(r.f) ?? 0) + 1);
217	  return out;
218	}
219	
220	// ── cards ──────────────────────────────────────────────────────────────────
221	export type ModCard = ModSummary & { banner: string | null };
222	
223	function toCard(m: GameMod, agg?: { avg: number | null; count: number }): ModCard {
224	  return {
225	    id: m.id, gameFamily: m.gameFamily, gameFamilyLabel: GAME_DISPLAY[m.gameFamily as GameFamily]?.name ?? m.gameFamily,
226	    name: m.name, slug: m.slug, category: m.category, source: m.source, iconUrl: m.iconUrl, description: m.description,
227	    downloads: m.downloads, featured: m.featured, paid: m.paid, verified: m.verifiedAt !== null, impact: m.impact,
228	    createdAt: m.createdAt.toISOString(), avgRating: agg?.avg ?? null, ratingCount: agg?.count ?? 0,
229	    url: m.url, sourceId: m.sourceId, appliesToVariant: m.appliesToVariant,
230	    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
231	    banner: m.galleryUrls[0] ?? null,
232	  };
233	}
234	
235	/** Full cards (with the first gallery image as banner) for ids, in the given order. */
236	export async function cardsByIds(ids: string[]): Promise<ModCard[]> {
237	  if (!ids.length) return [];
238	  const rows = await db.gameMod.findMany({ where: { id: { in: ids }, active: true, upstreamOk: true } });
239	  const aggs = await db.modRating.groupBy({ by: ["gameModId"], where: { gameModId: { in: ids } }, _avg: { rating: true }, _count: { rating: true } });
240	  const agg = new Map(aggs.map((a) => [a.gameModId, { avg: a._avg.rating, count: a._count.rating }]));
241	  const byId = new Map(rows.map((r) => [r.id, toCard(r, agg.get(r.id))]));
242	  return ids.map((id) => byId.get(id)).filter((x): x is ModCard => !!x);
243	}
244	
245	/** Adds each mod's first real gallery image (GameMod.galleryUrls[0]) as its card banner. */
246	export async function withBanners<T extends ModSummary>(mods: T[]): Promise<(T & { banner: string | null })[]> {
247	  if (!mods.length) return [];
248	  const rows = await db.gameMod.findMany({ where: { id: { in: mods.map((m) => m.id) } }, select: { id: true, galleryUrls: true } });
249	  const gal = new Map(rows.map((r) => [r.id, r.galleryUrls[0] ?? null]));
250	  return mods.map((m) => ({ ...m, banner: gal.get(m.id) ?? null }));
251	}
