48	export function query(qs?: Record<string, string | number | undefined>) {
49	  if (!qs) return "";
50	  const u = new URLSearchParams();
51	  for (const [k, v] of Object.entries(qs)) if (v !== undefined && v !== "" && v !== null) u.set(k, String(v));
52	  const s = u.toString();
53	  return s ? `?${s}` : "";
54	}
