135	/** "today" / "9d ago" / "4 mo ago" / "2 yr ago" from a real upstream timestamp. */
136	export function ago(iso: string | null | undefined): string | null {
137	  if (!iso) return null;
138	  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 86_400_000);
139	  if (days < 1) return "today";
140	  if (days < 60) return `${days}d ago`;
141	  if (days < 730) return `${Math.round(days / 30)} mo ago`;
142	  return `${Math.round(days / 365)} yr ago`;
143	}
144	const daysSince = (iso: string | null) => (iso ? Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 86_400_000)) : 99999);
