146	/** Real total downloads as a counter: {value, dec, suf} for data-au-count. */
147	export function countParts(total: number): { value: string; dec: number; suf: string } {
148	  if (total >= 1e9) { const v = total / 1e9; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "B" }; }
149	  if (total >= 1e6) { const v = total / 1e6; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "M" }; }
150	  if (total >= 1e3) { const v = total / 1e3; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "K" }; }
151	  return { value: String(total), dec: 0, suf: "" };
152	}
