209	/** Tile illustration: the design's animated CSS kinds, else the category's card art on its gradient. */
210	function ill(kind: string | undefined, card: string) {
211	  if (kind === "tick") return `<div class="ti ti-tick">${"<i></i>".repeat(16)}</div>`;
212	  if (kind === "nodes") return `<div class="ti ti-nodes"><i></i><i></i><i></i><i></i><b></b></div>`;
213	  if (kind === "terrain") return `<div class="ti ti-terrain"><i></i><i></i><i></i></div>`;
214	  if (kind === "path") return `<div class="ti ti-path"><i></i><i></i><i></i></div>`;
215	  if (kind === "gear") return `<div class="ti ti-gear"><i></i><i></i></div>`;
216	  return `<div class="ti" style="background:linear-gradient(135deg,var(--c1),var(--c2));overflow:hidden"><svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%;display:block" aria-hidden="true">${CARD_ILL[card] ?? CARD_ILL.core}</svg></div>`;
