1	import "server-only";
2	import { notFound } from "next/navigation";
3	import { TAX, categoryCounts, isTaxKey, queryMods, type TaxSort } from "./mods-taxonomy";
4	import { esc, type NxmLoad } from "./lib";
5	import { attr, browseHref, familyOr404, gameArt, gameHref, itemListLd, n, xmodCard, type Family } from "./mods-lib";
6	
7	/**
8	 * /mods/games/[family]/all — the "All Minecraft mods" design as the paginated,
9	 * filterable, searchable browse page for every family. One real
10	 * queryCatalogMods() call per request: ?q (name/category/description search),
11	 * ?category (the family's real categories), ?sort, ?page. Totals are real
12	 * counts, never the design's snapshot.
13	 */
14	const PER = 12;
15	const SORTS: { key: string; sort: TaxSort; label: string }[] = [
16	  { key: "downloads", sort: "downloads", label: "Most downloaded" },
17	  { key: "latest", sort: "latest", label: "Newest in NxLabs" },
18	  { key: "featured", sort: "featured", label: "Featured first" },
19	];
20	const DEFAULT_SORT = "downloads";
21	
22	type Q = { q: string; category: string; sort: string; page: number };
23	function parse(p: Record<string, string>): Q {
24	  return {
25	    q: (p.q ?? "").trim().slice(0, 100),
26	    category: (p.category ?? "").trim(),
27	    sort: SORTS.some((s) => s.key === p.sort) ? p.sort : DEFAULT_SORT,
28	    page: Math.max(1, Math.floor(Number(p.page) || 1)),
29	  };
30	}
31	const link = (f: Family, q: Q, over: Partial<Q>) => {
32	  const v = { ...q, ...over };
33	  return browseHref(f.family, {
34	    q: v.q || undefined, category: v.category || undefined,
35	    sort: v.sort !== DEFAULT_SORT ? v.sort : undefined, page: v.page > 1 ? v.page : undefined,
36	  });
37	};
38	
39	/** The family's NxLabs categories with real counts; a category it doesn't have is not a page. */
40	async function categories(f: Family, q: Q) {
41	  const cats = await categoryCounts(f.family);
42	  if (q.category && (!isTaxKey(q.category) || !cats.some((c) => c.cat.key === q.category))) notFound();
43	  return cats;
44	}
45	
46	export async function meta(p: Record<string, string>) {
47	  const f = await familyOr404(p.family);
48	  const q = parse(p);
49	  await categories(f, q);
50	  const bits = [q.category && TAX[q.category]?.label, q.q && `“${q.q}”`, q.page > 1 && `page ${q.page}`].filter(Boolean).join(", ");
51	  return {
52	    title: `All ${f.label} mods${bits ? ` (${bits})` : ""} — NxLabs`,
53	    description: `Browse all ${n(f.count)} verified ${f.label} mods and plugins, each linked to its real source, with real download counts.`,
54	    crumb: `All ${f.label} mods`,
55	    ...(q.q ? { noindex: true } : {}),
56	    ...(gameArt(f.family).hero ? { image: gameArt(f.family).hero! } : {}),
57	  };
58	}
59	
60	export async function load(p: Record<string, string>): Promise<NxmLoad> {
61	  const f = await familyOr404(p.family);
62	  const q = parse(p);
63	  const [cats, res] = await Promise.all([
64	    categories(f, q),
65	    queryMods({
66	      family: f.family, q: q.q || undefined, key: q.category && isTaxKey(q.category) ? q.category : undefined,
67	      sort: SORTS.find((s) => s.key === q.sort)!.sort, page: q.page, perPage: PER,
68	    }),
69	  ]);
70	  const cur = { ...q, page: res.page };
71	
72	  const sortHtml = SORTS.map((s) =>
73	    `<button type="button" data-s="${s.key}" data-href="${attr(link(f, cur, { sort: s.key, page: 1 }))}" aria-pressed="${s.key === q.sort}">${esc(s.label)}</button>`).join("");
74	
75	  // chips: the game's real categories by size; the active one always shown
76	  let shown = cats.slice(0, 10);
77	  if (q.category && !shown.some((c) => c.cat.key === q.category)) shown = [...shown, cats.find((c) => c.cat.key === q.category)!];
78	  const chip = (label: string, cat: string, count: number | null) =>
79	    `<button type="button" class="fc" data-c="${attr(cat)}" data-href="${attr(link(f, cur, { category: cat, page: 1 }))}" aria-pressed="${cat === q.category}">${esc(label)}${count != null ? ` <small style="opacity:.6">${n(count)}</small>` : ""}</button>`;
80	  const chipsHtml = cats.length > 1 ? chip("All", "", null) + shown.map((c) => chip(c.cat.label, c.cat.key, c.count)).join("") : "";
81	
82	  const from = res.total ? (res.page - 1) * res.perPage + 1 : 0;
83	  const to = Math.min(res.total, res.page * res.perPage);
84	  const scope = [q.category && `in ${TAX[q.category]?.label ?? q.category}`, q.q && `for “${q.q}”`].filter(Boolean).join(" ");
85	  const countText = res.total ? `Showing ${n(from)}–${n(to)} of ${n(res.total)}${scope ? ` ${scope}` : ""}` : `No ${f.label} mods ${scope || "yet"}`;
86	
87	  const grid = res.mods.map((m, i) => xmodCard(m, `b${i}`)).join("");
88	  const empty = res.total
89	    ? ""
90	    : `<p class="mb-empty" id="mb-empty">No ${esc(f.label)} mods match. Try another category, or <a href="${attr(browseHref(f.family))}">clear the search</a>.</p>`;
91	
92	  return {
93	    slots: {
94	      "game.name": f.label,
95	      "game.href": gameHref(f.family),
96	      "browse.href": browseHref(f.family),
97	      "game.count": n(f.count),
98	      "q": q.q,
99	      "hidden:html": [q.category && `<input type="hidden" name="category" value="${attr(q.category)}">`,
100	        q.sort !== DEFAULT_SORT && `<input type="hidden" name="sort" value="${attr(q.sort)}">`].filter(Boolean).join(""),
101	      "sort:html": sortHtml,
102	      "chips:html": chipsHtml,
103	      "count": countText,
104	      "grid:html": grid,
105	      "empty:html": empty,
106	      "pager:html": pager(f, cur, res.totalPages),
107	    },
108	    data: {},
109	    crumb: `All ${f.label} mods`,
110	    trail: [{ name: "NxLabs", path: "/mods" }, { name: `${f.label} mods`, path: `/mods/games/${f.family}` }, { name: "All mods", path: `/mods/games/${f.family}/all` }],
111	    jsonLd: res.mods.length ? [itemListLd(`All ${f.label} mods, page ${res.page}`, res.mods)] : [],
112	  };
113	}
114	
115	function pager(f: Family, q: Q, pages: number) {
116	  if (pages <= 1) return "";
117	  const p = q.page;
118	  const want = [...new Set([1, p - 2, p - 1, p, p + 1, p + 2, pages])].filter((x) => x >= 1 && x <= pages).sort((a, b) => a - b);
119	  let nums = "", last = 0;
120	  for (const x of want) {
121	    if (last && x - last > 1) nums += '<span class="pg-gap">…</span>';
122	    nums += `<a class="pg-n${x === p ? " on" : ""}" href="${attr(link(f, q, { page: x }))}"${x === p ? ' aria-current="page"' : ""}>${n(x)}</a>`;
123	    last = x;
124	  }
125	  const prev = p > 1 ? `<a class="pg-prev" href="${attr(link(f, q, { page: p - 1 }))}" rel="prev">← Previous</a>` : '<span class="pg-prev is-off" aria-disabled="true">← Previous</span>';
126	  const next = p < pages ? `<a class="pg-next" href="${attr(link(f, q, { page: p + 1 }))}" rel="next">Next →</a>` : '<span class="pg-next is-off" aria-disabled="true">Next →</span>';
127	  return `<nav class="pgn" aria-label="Pagination">${prev}<div class="pg-nums">${nums}</div>${next}</nav>
128	  <p class="pg-note">Page ${n(p)} of ${n(pages)} · ${PER} per page</p>`;
129	}
130

