const fs = require('fs');
const ts = fs.readFileSync('app/nxm/_data/mods-lib.ts','utf8');
const start = ts.indexOf('const CARD_ILL');
const braceStart = ts.indexOf('{', start);
// find matching closing brace considering nested braces in svg attrs (there are none at top structure since keys are simple)
let depth=0, i=braceStart, end=-1;
for (; i<ts.length; i++){
  if (ts[i]==='{') depth++;
  else if (ts[i]==='}') { depth--; if(depth===0){end=i;break;} }
}
const body = ts.slice(braceStart+1, end);
// split entries by regex: key: '...svg...',
const re = /(\w+): '((?:[^'\\\\]|\\\\.)*)'/g;
let mch, entries=[];
while ((mch = re.exec(body))) entries.push([mch[1], mch[2]]);
console.log(entries.map(e=>e[0]).join(','));
const cats = [
 ['performance','perf','#3FD89A','#3EDCF2'],
 ['library','core','#6F8DFF','#B98CFF'],
 ['admin','shield','#FF9A5C','#FF5FA8'],
 ['economy','coin','#FFD27A','#FF9A5C'],
 ['worldgen','wave','#3FD89A','#4E8DFF'],
 ['maps','pin','#3EDCF2','#7B5CFF'],
 ['items','blade','#FF6FA8','#B98CFF'],
 ['vehicles','car','#4E8DFF','#3EDCF2'],
 ['cosmetics','brush','#E04BD6','#7B3AF5'],
 ['qol','gear','#FFB36B','#FF6FA8'],
 ['social','chat','#6FB8FF','#9B6BFF'],
 ['mobs','paw','#E04BD6','#FF6FA8'],
 ['tech','circuit','#3EDCF2','#4E6BFF'],
 ['modes','target','#E04BD6','#7B3AF5'],
 ['building','cube','#FFD27A','#3FD89A'],
 ['gameplay','wave','#3EDCF2','#4E8DFF'],
];
const map = Object.fromEntries(entries);
let html = '<html><body style=\"background:#0B1030;display:flex;flex-wrap:wrap;gap:12px;padding:20px\">';
for (const [label, card, c1, c2] of cats){
  const svg = map[card] || 'MISSING';
  html += '<div style=\"width:220px\"><div style=\"width:200px;height:120px;border-radius:12px;overflow:hidden;background:linear-gradient(135deg,'+c1+','+c2+')\"><svg viewBox=\"0 0 200 120\" width=\"200\" height=\"120\">'+svg+'</svg></div><p style=\"color:#fff;font:12px sans-serif\">'+label+' / '+card+'</p></div>';
}
html += '</body></html>';
fs.writeFileSync('/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/mod-icons/cardill.html', html);
"

