.au-gauge .val small{color:var(--muted);font-size:.78rem}
.au-spark{position:relative}
.au-spark svg{display:block;width:100%;overflow:visible}
.au-spark .ln{fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.au-spark .ar{opacity:.9}
.au-spark .pt{fill:#fff;stroke:rgba(110,140,255,.8);stroke-width:4;paint-order:stroke;opacity:0;transition:opacity var(--au-small)}
.au-spark:hover .pt{opacity:1}
.au-spark .tip{position:absolute;top:0;left:0;padding:4px 9px;border-radius:8px;background:rgba(16,22,52,.97);border:1px solid rgba(160,150,255,.35);font:800 .76rem var(--f-display);color:#fff;pointer-events:none;opacity:0;transform:translate(-50%,-130%);transition:opacity var(--au-small)}
.au-spark:hover .tip{opacity:1}
.au-bars{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;height:100%}
.au-bars .b{position:relative;flex:1;display:flex;flex-direction:column;align-items:center;gap:10px;height:100%;justify-content:flex-end;cursor:default}
.au-bars .b i{position:relative;width:12px;height:100%;border-radius:12px;background:rgba(255,255,255,.05);overflow:hidden}
.au-bars .b i::after{content:"";position:absolute;left:0;right:0;bottom:0;height:calc(var(--v) * 100%);border-radius:12px;background:linear-gradient(0deg,#3A6BFF,#6FB8FF);box-shadow:0 0 14px rgba(80,140,255,.7);transform:scaleY(0);transform-origin:bottom;transition:transform 1s var(--au-out) calc(var(--k) * 60ms),filter var(--au-small)}
.au-bars.in .b i::after{transform:scaleY(1)}
.au-bars .b:hover i::after,.au-bars .b.on i::after{background:linear-gradient(0deg,#5B55FF,#7DEBFF);filter:brightness(1.25)}
.au-bars .b span{font-size:.74rem;color:var(--muted)}.au-bars .b.on span{color:#fff;font-weight:700}
.au-bars .b em{position:absolute;bottom:calc(var(--v) * (100% - 26px) + 34px);font:800 .72rem var(--f-display);font-style:normal;padding:3px 7px;border-radius:7px;background:rgba(16,22,52,.97);border:1px solid rgba(160,150,255,.35);color:#fff;opacity:0;transform:translateY(4px);transition:opacity var(--au-small) var(--au-out),transform var(--au-small) var(--au-out)}
.au-bars .b:hover em,.au-bars .b.on em{opacity:1;transform:none}
.au-wave{display:block;width:100%;overflow:visible}
.au-wave path{fill:none;stroke-width:2.4;stroke-linecap:round}
@media (prefers-reduced-motion:no-preference){.au-wave .mv{animation:auWave 6s linear infinite}.au-wave .mv2{animation:auWave 9s linear infinite reverse}}

/* ---------- animated icons ---------- */
.au-ic{display:inline-block;width:24px;height:24px;flex:none;vertical-align:middle;overflow:visible}
.au-ic *{fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transform-box:fill-box;transform-origin:center}
.au-ic.grad *{stroke:url(#au-g)}
.au-ic .fl{fill:currentColor;stroke:none}.au-ic.grad .fl{fill:url(#au-g)}
.au-tile{position:relative;display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:var(--au-glass-2),rgba(18,24,58,.8);box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(160,160,255,.18),0 10px 24px -12px rgba(80,80,255,.8);color:#CFE0FF}
.au-tile::before{content:"";position:absolute;inset:8px;border-radius:50%;background:radial-gradient(circle,rgba(110,140,255,.45),transparent 70%);filter:blur(6px);opacity:.7;transition:opacity var(--au-med)}
.au-tile:hover::before{opacity:1}
.au-tile .au-ic{position:relative;width:26px;height:26px}
/* per-icon motion: plays on hover of the icon or its trigger parent, or once with .play */
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .led{animation:icBlink .9s var(--au-io) calc(var(--d,0)*120ms) 2}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .mer{animation:icSpin 1.1s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .draw{animation:icDraw .8s var(--au-out) both}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .zap{animation:icZap .7s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .drift{animation:icDrift 1.2s var(--au-io)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .shk{animation:icShackle .9s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .flap{animation:icFlap .9s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .swing{transform-origin:50% 0;animation:icSwing .9s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .lens{animation:icLens .8s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .press{animation:icPress .5s var(--au-io) calc(var(--d,0)*140ms) 2}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .grow{transform-origin:50% 100%;animation:icGrow .8s var(--au-out) calc(var(--d,0)*90ms) both}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .pin{animation:icPin .8s var(--au-io) calc(var(--d,0)*70ms)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .stack{animation:icStack .8s var(--au-out) calc(var(--d,0)*90ms)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .launch{animation:icLaunch 1s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .spin{animation:icSpin .9s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .nudge{animation:icNudge .7s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .gear{animation:icGear 1s var(--au-out)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .bob{animation:icBob .7s var(--au-out) calc(var(--d,0)*120ms)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .twk{animation:icTwinkle .9s var(--au-out) calc(var(--d,0)*120ms)}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .caret{animation:icBlink .5s steps(2) 3}
:is(.au-ic:hover,.au-hov:hover .au-ic,.au-ic.play) .slide{animation:icSlide .8s var(--au-out)}



















/* ---------- animated logo ---------- */
.au-logo{display:inline-block;overflow:visible}
.au-logo .o{fill:none;stroke:url(#au-lg);stroke-width:.9;stroke-linejoin:round}
.au-logo .f{fill:url(#au-lg);opacity:0}
.au-logo .sh{fill:url(#au-sheen);opacity:.9;mix-blend-mode:screen}
.au-logo.play .o{stroke-dasharray:var(--len);stroke-dashoffset:var(--len);animation:lgDraw 1.4s var(--au-io) forwards}
.au-logo.play .f{animation:lgFill .8s var(--au-out) 1.1s forwards}
.au-logo.play .shr{animation:lgSheen 1.6s var(--au-io) 1.7s}
.au-logo.idle .shr{animation:lgSheen 1.6s var(--au-io) infinite 3s}
.au-logo:hover .shr{animation:lgSheen 1.2s var(--au-io)}



@media (prefers-reduced-motion:reduce){.au-ic *,.au-logo *,.au-btn,.au-btn::before,.au-chip .d,.au-prog i::after,.au-skel{animation:none!important}.au-logo .f{opacity:1}}
/* ---------- retrofit: existing page elements adopt the aurora motion language ---------- */
.btn{position:relative;overflow:hidden;transition:transform var(--au-fast) var(--au-out),box-shadow var(--au-med) var(--au-out),background-color var(--au-small),border-color var(--au-small),color var(--au-small)}
.btn:active{transform:scale(.97);transition-duration:80ms}
.btn-grad{box-shadow:inset 0 1px 0 rgba(255,255,255,.3),0 10px 28px -12px rgba(92,80,255,.9)}
.btn-grad:hover{box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 16px 38px -12px rgba(110,90,255,1),0 0 0 4px rgba(123,92,255,.12)}
:is(.dm-search,.em-dom,.g-q,.m-dom,.d-big,.au-search){isolation:isolate}
:is(.dm-search,.em-dom,.g-q,.m-dom,.d-big)::after{content:"";position:absolute;inset:-5px;border-radius:inherit;background:var(--au-grad);filter:blur(12px);opacity:0;transform:scale(.97);z-index:-1;pointer-events:none;transition:opacity var(--au-med) var(--au-out),transform var(--au-med) var(--au-out)}
:is(.dm-search,.em-dom,.g-q,.m-dom,.d-big):focus-within::after{opacity:.3;transform:scale(1)}
:is(.dm-search,.em-dom):focus-within{transform:translateY(-2px)}
.dm-search,.em-dom{transition:border-color var(--au-small) var(--au-out),box-shadow var(--au-med) var(--au-out),transform var(--au-med) var(--au-out),background-color var(--au-small)!important}
.dm-res{transform-origin:top center;animation:auDrop var(--au-med) var(--au-out) both!important}

