  & .nxm-lib-nav a:hover { color: var(--ink); border-color: var(--line-3); }

  & .nxm-lib-sec { padding-block: 56px 8px; border-top: 1px solid var(--line); margin-top: 40px; scroll-margin-top: 24px; }
  & .nxm-lib-sec-h { display: grid; gap: 6px; margin-bottom: 26px; max-width: 70ch; }
