6	/**
7	 * The new pages render their prices on the server in the visitor's currency.
8	 * When the visitor picks another currency in the footer switcher (which saves
9	 * the `nx_currency` cookie), reload so the server re-renders every price in it.
10	 */
11	export function CurrencyReload({ initial }: { initial: string }) {
12	  const { currency } = useCurrency();
13	  const first = useRef(initial);
14	  useEffect(() => {
15	    if (currency && currency !== first.current) window.location.reload();
16	  }, [currency]);
17	  return null;
18	}
