1	"use client";
2	
3	// Searchable currency picker with flags. Reads/writes the shared currency context
4	// (persisted to a cookie), so choosing a currency re-formats every price that goes
5	// through useDisplayMoney() and sticks across navigation. DISPLAY ONLY — this
6	// changes how prices are shown, not what is charged.
7	
8	import { useEffect, useMemo, useRef, useState } from "react";
9	import { CURRENCIES, currencyCountry } from "@/lib/currency";
10	import { useCurrency } from "./CurrencyContext";
11	
12	// Most-used currencies float to the top; every other supported currency follows
13	// alphabetically, so ALL of them are reachable (via scroll or the search box).
14	const POPULAR = [
15	  "USD", "EUR", "GBP", "CAD", "AUD", "NZD", "CHF", "SEK", "NOK", "DKK", "PLN",
16	  "INR", "JPY", "CNY", "KRW", "SGD", "HKD", "AED", "SAR", "BRL", "MXN", "ZAR",
17	  "VND", "PHP", "THB", "IDR", "MYR", "TRY", "RUB",
18	];
19	
20	/** A country flag, SELF-HOSTED under /public/flags (served from our own origin so
21	 *  it works everywhere — no external CDN that a region/ad-blocker might block, and
22	 *  the CSP 'self' always allows it). Renders a neutral chip if the flag is absent. */
23	function Flag({ code, size = 18 }: { code: string; size?: number }) {
24	  const cc = currencyCountry(code);
25	  const [ok, setOk] = useState(true);
26	  if (!ok || !cc) {
27	    return <span className="inline-block shrink-0 rounded-[2px] bg-white/10" style={{ width: size, height: Math.round(size * 0.75) }} aria-hidden />;
28	  }
29	  return (
30	    <img
31	      src={`/flags/${cc}.png`}
32	      width={size}
33	      height={Math.round(size * 0.75)}
34	      alt=""
35	      loading="lazy"
36	      onError={() => setOk(false)}
37	      className="shrink-0 rounded-[2px] object-cover"
38	    />
39	  );
40	}
