42	export function CurrencySwitcher({ className = "" }: { className?: string }) {
43	  const { currency, setCurrency } = useCurrency();
44	  const [open, setOpen] = useState(false);
45	  const [dropUp, setDropUp] = useState(false);
46	  // Real bug found live: the panel is a fixed 256px wide, anchored via `right-0`
47	  // to the trigger — fine when the trigger sits near the viewport's right edge,
48	  // but on a narrow mobile layout where the trigger ends up further left (e.g.
49	  // the footer's stacked mobile column), `right-0` still extends the panel a
50	  // full 256px further left, pushing its left edge off-screen with no bounds
51	  // check at all (unlike `dropUp`, which already measures before deciding).
52	  // Same idea, horizontal axis: measure whether there's 256px of room to the
53	  // LEFT of the trigger's right edge; if not, anchor from the left instead.
54	  const [dropLeft, setDropLeft] = useState(false);
55	  const [query, setQuery] = useState("");
56	  const wrapRef = useRef<HTMLDivElement>(null);
57	  const searchRef = useRef<HTMLInputElement>(null);
58	
59	  // Full currency names for display + search (e.g. "Vietnamese Dong"), native to
60	  // the platform — no data table to maintain. Falls back to the code if absent.
61	  const names = useMemo(() => {
62	    try {
63	      return new Intl.DisplayNames(["en"], { type: "currency" });
64	    } catch {
65	      return null;
66	    }
67	  }, []);
68	  const nameOf = (code: string) => {
69	    try {
70	      return names?.of(code) ?? code;
71	    } catch {
72	      return code;
73	    }
74	  };
75	
76	  // Ordered list: popular first, then the rest A–Z.
77	  const allCodes = useMemo(() => {
78	    const pop = POPULAR.filter((c) => CURRENCIES[c]);
79	    const rest = Object.keys(CURRENCIES)
80	      .filter((c) => !pop.includes(c))
81	      .sort();
82	    return [...pop, ...rest];
83	  }, []);
84	
85	  const filtered = useMemo(() => {
86	    const q = query.trim().toLowerCase();
87	    if (!q) return allCodes;
88	    return allCodes.filter(
89	      (c) => c.toLowerCase().includes(q) || nameOf(c).toLowerCase().includes(q),
90	    );
91	    // eslint-disable-next-line react-hooks/exhaustive-deps
92	  }, [query, allCodes]);
93	
94	  // Close on outside click / Escape; focus the search when opening.
95	  useEffect(() => {
96	    if (!open) return;
97	    // Open upward when there isn't room below (e.g. the marketing footer), and
98	    // anchor from the left when there isn't 256px of room to the left of the
99	    // trigger's right edge (e.g. a mobile layout where this sits further left).
100	    const rect = wrapRef.current?.getBoundingClientRect();
101	    if (rect) {
102	      setDropUp(window.innerHeight - rect.bottom < 340);
103	      setDropLeft(rect.right < 256);
104	    }
105	    const onDown = (e: MouseEvent) => {
106	      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
107	    };
108	    const onKey = (e: KeyboardEvent) => {
109	      if (e.key === "Escape") setOpen(false);
110	    };
111	    document.addEventListener("mousedown", onDown);
112	    document.addEventListener("keydown", onKey);
113	    const t = setTimeout(() => searchRef.current?.focus(), 0);
114	    return () => {
115	      document.removeEventListener("mousedown", onDown);
116	      document.removeEventListener("keydown", onKey);
117	      clearTimeout(t);
118	    };
119	  }, [open]);
120	
121	  function choose(code: string) {
122	    setCurrency(code);
123	    setOpen(false);
124	    setQuery("");
125	  }
126	
127	  const meta = CURRENCIES[currency];
128	
129	  return (
130	    <div ref={wrapRef} className={`relative ${className}`}>
131	      <button
132	        type="button"
133	        onClick={() => setOpen((v) => !v)}
134	        aria-haspopup="listbox"
135	        aria-expanded={open}
136	        aria-label="Display currency"
137	        className="inline-flex items-center gap-1.5 rounded-md border border-white/10 bg-navy-900/70 px-2 py-1 text-xs font-medium text-slate-200 outline-none transition-colors hover:border-white/25 focus:border-brand-500/60"
138	      >
139	        <Flag code={currency} size={16} />
140	        <span>{currency}</span>
141	        <span className="text-slate-500">{meta?.symbol.trim()}</span>
142	        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden className="text-slate-500">
143	          <path d="M6 9l6 6 6-6" />
144	        </svg>
145	      </button>
146	
147	      {open && (
148	        <div
149	          className={`absolute z-50 w-64 max-w-[calc(100vw-1.5rem)] overflow-hidden rounded-xl border border-white/10 bg-navy-950/95 shadow-2xl backdrop-blur-xl ${dropUp ? "bottom-full mb-1.5" : "mt-1.5"} ${dropLeft ? "left-0" : "right-0"}`}
150	        >
151	          <div className="border-b border-white/[0.06] p-2">
152	            <input
153	              ref={searchRef}
154	              value={query}
155	              onChange={(e) => setQuery(e.target.value)}
156	              placeholder="Search currency…"
157	              className="w-full rounded-lg border border-white/10 bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 outline-none placeholder:text-slate-500 focus:border-brand-500/60"
158	            />
159	          </div>
160	          <ul role="listbox" className="max-h-72 overflow-y-auto py-1">
161	            {filtered.length === 0 && (
162	              <li className="px-3 py-4 text-center text-xs text-slate-500">No match</li>
163	            )}
164	            {filtered.map((c) => (
165	              <li key={c}>
166	                <button
167	                  type="button"
168	                  role="option"
169	                  aria-selected={c === currency}
170	                  onClick={() => choose(c)}
171	                  className={`flex w-full items-center gap-2.5 px-3 py-1.5 text-left text-xs transition-colors hover:bg-white/[0.06] ${
172	                    c === currency ? "bg-brand-500/15 text-white" : "text-slate-300"
173	                  }`}
174	                >
175	                  <Flag code={c} size={18} />
176	                  <span className="font-semibold">{c}</span>
177	                  <span className="truncate text-slate-500">{nameOf(c)}</span>
178	                  <span className="ml-auto shrink-0 text-slate-500">{CURRENCIES[c].symbol.trim()}</span>
179	                </button>
180	              </li>
181	            ))}
182	          </ul>
183	        </div>
184	      )}
185	    </div>
186	  );
187	}
